import { continuingStories, continuingProjects } from './continuing-content.js';
import { testBenchProjects } from './testbench-content.js';
import { neighbourUnlocked, lockReason } from './neighbour-model.js';
import { characterPortrait } from './characters.js';
import { pinButton } from './objective-ui.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const introduction=(state,story)=>state.restoration.opened.includes(story.building)?story.intro:({rowan:'When Mabel’s oven is warm again, Rowan has a few ideas for sharing its work. Your early projects and restoration will make them possible.',mira:'Mira and Nell dream of taking the library’s stories beyond its walls. First, help them build their earlier tools and reopen the reading room.',elio:'Elio has plans for the nursery’s next season. Your early experiments and greenhouse repairs will give those plans a place to grow.'}[story.npc]);
const visit=(id,label)=>`<button type="button" class="button outline" data-neighbour="project" data-id="${id}">${label}</button>`;
export function testBenchLedger(state) {
  return `<div class="dialog-top"><span class="eyebrow">MIRA’S TEST BENCH</span><button type="button" class="icon-button" data-neighbour="close" aria-label="Close">×</button></div><div class="apprentice-intro">${characterPortrait('mira','community-portrait')}<div><h2>A promise worth checking</h2><p>“Before a repair leaves the bench, let’s find out what would prove it wrong.”</p></div></div><p>Write tests that accept correct tools and catch carefully planted faults. Your hints are free, and every attempt is welcome.</p>${pinButton('testing')}<ol class="neighbour-project-list">${testBenchProjects.map(p=>`<li><span class="lesson-knot">${state.neighbours.completed.includes(p.id)?'✓':'⌁'}</span><div><strong>${p.title}</strong><small>${esc(state.neighbours.completed.includes(p.id)?p.outcome:neighbourUnlocked(state,p)?p.story:lockReason(state,p))}</small></div>${visit(p.id,state.neighbours.completed.includes(p.id)?'Revisit tests':'Inspect')}</li>`).join('')}</ol>`;
}
export function continuingInvitation(state,npc) {
  const story=continuingStories.find(s=>s.npc===npc),group=continuingProjects.filter(p=>p.npc===npc),pending=group.find(p=>!state.neighbours.completed.includes(p.id))||group.at(-1);
  return `<aside class="neighbour-restoration-note"><p class="eyebrow">OUR NEXT CHAPTER</p><h3>${story.title}</h3><p>${introduction(state,story)}</p><a class="button outline" href="#stories/project/${pending.id}">Continue with ${story.name} →</a>${pinButton('story:'+npc)}</aside>`;
}
export function renderContinuing(state) {
  return `<section class="neighbours-root continuing-world" data-view="stories"><header class="court-heading"><div><p class="eyebrow">FAMILIAR FACES · NEW POSSIBILITIES</p><h1>A village growing with you</h1><p>The doors are open. These next chapters put your later learning to work.</p></div><a class="button outline" href="#village">Back to Hearthwick</a></header><div class="continuing-stories">${continuingStories.map(story=>`<article class="continuing-story"><header>${characterPortrait(story.npc,'community-portrait')}<div><p class="eyebrow">WITH ${story.name.toUpperCase()}</p><h2>${story.title}</h2></div></header><p>${introduction(state,story)}</p>${pinButton('story:'+story.npc)}<ol>${continuingProjects.filter(p=>p.npc===story.npc).map(p=>`<li><h3>${p.title}</h3><p>${esc(state.neighbours.completed.includes(p.id)?p.outcome:p.story)}</p><small>${esc(state.neighbours.completed.includes(p.id)?'A working part of the village':neighbourUnlocked(state,p)?'Ready when you are':lockReason(state,p))}</small>${visit(p.id,state.neighbours.completed.includes(p.id)?'Revisit our work':'Hear the next chapter')}${state.neighbours.completed.includes(p.id)?`<button class="text-button" data-neighbour="use" data-id="${p.id}">See it working →</button>`:''}</li>`).join('')}</ol></article>`).join('')}</div><p class="neighbour-status sr-only" role="status"></p></section>`;
}
export function continuingReport(p,result) {
  const headings={ 'rowan-shared-oven':'The shared oven ledger','mira-library-round':'Nell’s traveling library','elio-care-ranges':'The nursery care board','rowan-tomorrow':'Tomorrow’s chalkboard','elio-heater-review':'The heater review plate','mira-reading-bag':'The reading bag’s collection'};
  return `<section class="working-round continuing-report"><h3>${headings[p.id]}</h3><p>${p.outcome}</p><pre>${esc(JSON.stringify(result,null,2))}</pre>${p.id==='elio-heater-review'?'<p>These are validation results for a human review. Keep a separate final test before trusting a new heater.</p>':''}<a href="#village">Visit the village →</a></section>`;
}
